const assets={"refresh-5632661e40cb.jpg":"","refresh-83e64f2e4849.jpg":""};
export function approvedImage(path,method){const value=assets[path.split("/").at(-1)];if(!value||!path.startsWith("/uploads/blog/"))return null;if(!["GET","HEAD"].includes(method))return new Response(null,{status:405});const data=Uint8Array.from(atob(value),c=>c.charCodeAt(0));return new Response(method==="HEAD"?null:data,{headers:{"Content-Type":"image/jpeg","Content-Length":String(data.length),"Cache-Control":"public,max-age=31536000,immutable","X-Content-Type-Options":"nosniff"}})}
